import React, { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4 flex flex-wrap items-center justify-between">
      <img src={logo} alt="Logo" className="h-12" />

      {/* Mobile menu toggle */}
      <div className="md:hidden ml-auto">
        <button
          onClick={() => setIsMenuOpen(!isMenuOpen)}
          className="text-2xl font-bold"
        >
          ☰
        </button>
      </div>

      {/* Full menu container */}
      <div
        className={`w-full md:flex md:items-center md:justify-between mt-4 md:mt-0 ${
          isMenuOpen ? 'block' : 'hidden'
        }`}
      >
        {/* Nav Links - centered */}
        <nav className="flex flex-col md:flex-row items-center justify-center gap-4 md:gap-8 text-[clamp(0.9rem,2vw,1.1rem)] font-semibold text-[#292929] w-full">
          <a href="#" className="text-[#f48f0f]">Home</a>
          <a href="#">About</a>
          <a href="#">Gallery</a>
          <a href="#">Education</a>
        </nav>

        {/* Button - right aligned on desktop */}
        <div className="flex justify-center md:justify-end mt-4 md:mt-0 w-full md:w-auto">
          <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
            Become a member
          </button>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
